function overlayDialog(e,o,i){o+=20,i+=20,$("#overlay-container").remove();let n=`
    <div id="overlay-container">
        <div class="ui-widget-overlay"></div>

        <div id="overlay-inner"
             class="ui-widget ui-widget-content ui-corner-all"
             style="width:${o}px;height:${i}px">

            <div class="ui-dialog-content">
                ${e}
            </div>

        </div>
    </div>
    `;$("body").append(n),$("#overlay-container").on("click",function(){closeOverlayDialog()}),$("#overlay-inner").on("click",function(e){e.stopPropagation()}),$(document).on("keydown.overlay",function(e){("Escape"===e.key||"Enter"===e.key)&&closeOverlayDialog()})}function closeOverlayDialog(){$("#overlay-container").fadeOut(200,function(){$(this).remove()}),$(document).off("keydown.overlay")}